<template><div class="routine-page"><div class="page-header-row"><div><span class="eyebrow">পরীক্ষা ব্যবস্থাপনা</span><h1>পরীক্ষা রুটিন</h1><p>পরীক্ষার তারিখ, সময়, শ্রেণি ও নম্বর এক নজরে দেখুন</p></div><div class="actions"><NuxtLink to="/exams/create" class="btn btn-primary"><icon name="plus" /> নতুন পরীক্ষা</NuxtLink><NuxtLink to="/reports" class="btn btn-outline">রিপোর্ট</NuxtLink></div></div><div class="summary-grid"><div class="summary-card green"><span><icon name="calendar" /></span><b>{{ exams.length }}</b><small>মোট পরীক্ষা</small></div><div class="summary-card blue"><span><icon name="clock" /></span><b>{{ upcoming.length }}</b><small>আসন্ন</small></div><div class="summary-card purple"><span><icon name="check" /></span><b>{{ completed.length }}</b><small>সম্পন্ন</small></div><div class="summary-card gold"><span><icon name="book" /></span><b>{{ subjectsCount }}</b><small>বিষয়</small></div></div><div class="filter-bar card"><div class="search-box"><icon name="search" /><input v-model="search" placeholder="পরীক্ষা খুঁজুন..." /></div><select v-model="filter" class="form-control compact"><option value="">সব পরীক্ষা</option><option value="upcoming">আসন্ন</option><option value="completed">সম্পন্ন</option></select></div><div v-if="loading" class="loading-state"><div class="spinner" /></div><div v-else-if="!visible.length" class="empty-card"><div class="empty-icon"><icon name="calendar" /></div><h3>কোনো পরীক্ষা পাওয়া যায়নি</h3><p>নতুন পরীক্ষা তৈরি করে রুটিন সাজান</p></div><div v-else class="exam-timeline"><article v-for="exam in visible" :key="exam.id" class="exam-card"><div class="date-column"><strong>{{ day(exam.start_date) }}</strong><span>{{ month(exam.start_date) }}</span><small>{{ year(exam.start_date) }}</small></div><div class="timeline-line" /><div class="exam-main"><div class="exam-top"><span class="type-chip">{{ exam.exam_type || exam.type || 'নিয়মিত' }}</span><span class="status" :class="exam.is_active===false?'inactive':'active'">{{ exam.is_active===false?'নিষ্ক্রিয়':'সক্রিয়' }}</span></div><h2>{{ exam.name_bn || exam.title_bn || exam.name_en || exam.title_en }}</h2><div class="facts"><span><icon name="academic" /> {{ exam.class?.name_bn || 'সব শ্রেণি' }}</span><span><icon name="clock" /> {{ time(exam.start_time) }} – {{ time(exam.end_time) }}</span><span><icon name="check" /> {{ exam.total_marks || 0 }} নম্বর</span><span><icon name="book" /> পাশ: {{ exam.passing_marks || 0 }}</span></div></div><NuxtLink :to="`/exams/${exam.id}`" class="view-btn">বিস্তারিত <icon name="arrow-right" /></NuxtLink></article></div></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useApiClient}from'~/utils/api';const api=useApiClient();const exams=ref<any[]>([]);const loading=ref(true);const search=ref('');const filter=ref('');const today=new Date();const upcoming=computed(()=>exams.value.filter(e=>e.start_date&&new Date(e.start_date)>=today));const completed=computed(()=>exams.value.filter(e=>e.end_date&&new Date(e.end_date)<today));const subjectsCount=computed(()=>new Set(exams.value.map(e=>e.subject_id).filter(Boolean)).size);const visible=computed(()=>exams.value.filter(e=>{const name=(e.name_bn||e.title_bn||e.name_en||'').toLowerCase();const match=!search.value||name.includes(search.value.toLowerCase());const f=filter.value==='upcoming'?upcoming.value.includes(e):filter.value==='completed'?completed.value.includes(e):true;return match&&f}));onMounted(async()=>{try{const r=await api.get('/exams?per_page=100');exams.value=r.data?.data?.data||r.data?.data||[]}catch(e){console.error(e)}finally{loading.value=false}});function day(v:string){return v?new Date(v).toLocaleDateString('bn-BD',{day:'numeric'}):'—'}function month(v:string){return v?new Date(v).toLocaleDateString('bn-BD',{month:'short'}):'—'}function year(v:string){return v?new Date(v).toLocaleDateString('bn-BD',{year:'numeric'}):''}function time(v:string){return v?.slice(0,5)||'—'}</script>
<style scoped>.routine-page{max-width:1250px;margin:0 auto;padding-bottom:2rem}.page-header-row{display:flex;justify-content:space-between;align-items:flex-end;gap:1rem;margin-bottom:1.3rem}.eyebrow{color:var(--color-primary);font:600 .78rem var(--font-bn)}.page-header-row h1{margin:.25rem 0;color:var(--color-primary);font:700 1.65rem var(--font-bn)}.page-header-row p{color:var(--color-text-light);font:.88rem var(--font-bn)}.actions{display:flex;gap:.5rem}.summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:.8rem;margin-bottom:1rem}.summary-card{display:grid;grid-template-columns:auto 1fr;align-items:center;column-gap:.7rem;padding:1rem;border-radius:15px;color:#fff}.summary-card span{display:grid;place-items:center;width:38px;height:38px;border-radius:11px;background:rgba(255,255,255,.17)}.summary-card b{font:800 1.35rem var(--font-sans)}.summary-card small{grid-column:2;color:rgba(255,255,255,.78);font:.72rem var(--font-bn)}.summary-card.green{background:linear-gradient(145deg,#176b45,#0e452d)}.summary-card.blue{background:linear-gradient(145deg,#17658f,#103b60)}.summary-card.purple{background:linear-gradient(145deg,#6e4da5,#41316f)}.summary-card.gold{background:linear-gradient(145deg,#bd8e20,#795a12)}.filter-bar{display:flex;gap:.7rem;padding:.7rem;margin-bottom:1rem}.search-box{display:flex;align-items:center;gap:.5rem;flex:1;padding:0 .75rem;background:var(--color-bg-muted);border-radius:10px}.search-box input{width:100%;padding:.65rem 0;border:0;outline:0;background:transparent;font:.86rem var(--font-bn)}.form-control.compact{width:150px}.exam-timeline{display:grid;gap:.7rem}.exam-card{display:grid;grid-template-columns:70px 3px 1fr auto;align-items:center;gap:1rem;padding:1rem;background:#fff;border:1px solid var(--color-border-light);border-radius:16px;box-shadow:var(--shadow-sm);transition:.2s}.exam-card:hover{transform:translateY(-2px);box-shadow:var(--shadow-md)}.date-column{text-align:center}.date-column strong,.date-column span,.date-column small{display:block}.date-column strong{color:var(--color-primary);font:800 1.35rem var(--font-sans)}.date-column span{color:var(--color-text);font:700 .8rem var(--font-bn)}.date-column small{color:var(--color-text-muted);font:.65rem var(--font-bn)}.timeline-line{height:58px;border-radius:99px;background:var(--color-accent)}.exam-top{display:flex;justify-content:space-between}.type-chip,.status{padding:.24rem .6rem;border-radius:99px;font:.68rem var(--font-bn)}.type-chip{color:#7857a9;background:#f0eafb}.status.active{color:#19724a;background:#e6f4ec}.status.inactive{color:#a05c35;background:#fff0e4}.exam-main h2{margin:.55rem 0;color:var(--color-text);font:700 1rem var(--font-bn)}.facts{display:flex;gap:1rem;flex-wrap:wrap;color:var(--color-text-light);font:.72rem var(--font-bn)}.facts span{display:inline-flex;align-items:center;gap:.3rem}.view-btn{display:inline-flex;align-items:center;gap:.3rem;color:var(--color-primary);font:600 .75rem var(--font-bn);white-space:nowrap}.empty-card{padding:3rem;text-align:center;background:#fff;border:1px dashed var(--color-border);border-radius:18px}.empty-icon{display:grid;place-items:center;width:54px;height:54px;margin:0 auto 1rem;border-radius:16px;color:var(--color-primary);background:var(--color-primary-50);font-size:1.4rem}.empty-card h3{font:700 1rem var(--font-bn)}.empty-card p{color:var(--color-text-light);font:.8rem var(--font-bn)}@media(max-width:700px){.page-header-row{align-items:flex-start;flex-direction:column}.summary-grid{grid-template-columns:repeat(2,1fr)}.filter-bar{flex-wrap:wrap}.search-box{min-width:100%}.form-control.compact{width:100%}.exam-card{grid-template-columns:55px 3px 1fr}.view-btn{grid-column:3}.facts{gap:.5rem}}
</style>
